import random

def get_bet():
    """Get user input for the bet amount."""
    while True:
        try:
            bet_amount = int(input("Enter the amount you want to bet: "))
            if bet_amount > 0:
                return bet_amount
            else:
                print("Your bet amount must be a positive integer. Please try again.")
        except ValueError:
            print("That's not a valid integer. Please try again.")

def roll_die(num_sides):
    """Roll a die with the given number of sides."""
    return random.randint(1, num_sides)

def flip_coin():
    """Flip a coin and return the result (heads or tails)."""
    return "heads" if random.random() < 0.5 else "tails"

def play_game():
    """Simulate a game of chance and handle the outcome."""
    bet_amount = get_bet()

    if random.random() < 0.5:  # Heads
        outcome = flip_coin()
    else:
        outcome = roll_die(6)  # Roll a fair six-sided die

    print(f"You bet ${bet_amount}. The outcome is {outcome}.")

    if outcome == "heads":
        print("You win! The coin landed on heads.")
    else:
        print("You lose. The die landed on", outcome, ".")

if __name__ == "__main__":
    play_game()
```

This program defines three functions: `get_bet()`, which gets the user's bet amount; `roll_die(num_sides)`, which rolls a die with the given number of sides; and `flip_coin()`, which simulates a coin flip. The `play_game()` function simulates a game of chance, gets the user's bet amount, rolls a die or simulates a coin flip, and handles the outcome by printing the result and the user's winnings or losses.
